#!/bin/bash
set -euo pipefail
PROJECT_DIR="$(cd "$(dirname "$0")/.." && pwd)"
mkdir -p "$PROJECT_DIR/.build/module-cache" "$PROJECT_DIR/.build/smc-tests"
export CLANG_MODULE_CACHE_PATH="$PROJECT_DIR/.build/module-cache"
TEST_ARCH="${OPENCHARGE_TEST_ARCH:-$(uname -m)}"
case "$TEST_ARCH" in arm64|x86_64) ;; *) echo "Unsupported test architecture" >&2; exit 1 ;; esac
swiftc -target "$TEST_ARCH-apple-macosx13.0" "$PROJECT_DIR/Sources/ChargeHardware/BatteryReader.swift" "$PROJECT_DIR/Sources/ChargeHardware/TelemetryMath.swift" "$PROJECT_DIR/Sources/ChargeHardware/SMCChargeController.swift" "$PROJECT_DIR/Sources/ChargeHardware/ChargeRecoveryStore.swift" "$PROJECT_DIR/Tests/HardwareSmoke/SMCChargeTests.swift" -o "$PROJECT_DIR/.build/smc-tests/check-$TEST_ARCH"
/usr/bin/arch "-$TEST_ARCH" "$PROJECT_DIR/.build/smc-tests/check-$TEST_ARCH"
swiftc -target "$TEST_ARCH-apple-macosx13.0" "$PROJECT_DIR/Sources/ChargeHardware/BatteryReader.swift" "$PROJECT_DIR/Sources/ChargeHardware/TelemetryMath.swift" "$PROJECT_DIR/Sources/ChargeHardware/SMCChargeController.swift" "$PROJECT_DIR/Sources/ChargeHardware/ChargeRecoveryStore.swift" "$PROJECT_DIR/Tests/HardwareSmoke/ChargeRecoveryTests.swift" -o "$PROJECT_DIR/.build/smc-tests/recovery-$TEST_ARCH"
/usr/bin/arch "-$TEST_ARCH" "$PROJECT_DIR/.build/smc-tests/recovery-$TEST_ARCH"
swiftc -target "$TEST_ARCH-apple-macosx13.0" "$PROJECT_DIR/Sources/ChargeHardware/BatteryReader.swift" "$PROJECT_DIR/Sources/ChargeHardware/TelemetryMath.swift" "$PROJECT_DIR/Sources/ChargeHardware/SMCFirmwareChargeController.swift" "$PROJECT_DIR/Sources/ChargeHardware/ChargeRecoveryStore.swift" "$PROJECT_DIR/Tests/HardwareSmoke/FirmwareChargeTests.swift" -o "$PROJECT_DIR/.build/smc-tests/firmware-$TEST_ARCH"
/usr/bin/arch "-$TEST_ARCH" "$PROJECT_DIR/.build/smc-tests/firmware-$TEST_ARCH"
swiftc -target "$TEST_ARCH-apple-macosx13.0" "$PROJECT_DIR/Sources/ChargeHardware/BatteryReader.swift" "$PROJECT_DIR/Sources/ChargeHardware/TelemetryMath.swift" "$PROJECT_DIR/Sources/ChargeHardware/SMCFirmwareChargeController.swift" "$PROJECT_DIR/Sources/ChargeHardware/ChargeRecoveryStore.swift" "$PROJECT_DIR/Tests/HardwareSmoke/FirmwareChargeCrashTests.swift" -o "$PROJECT_DIR/.build/smc-tests/firmware-crash-$TEST_ARCH"
/usr/bin/arch "-$TEST_ARCH" "$PROJECT_DIR/.build/smc-tests/firmware-crash-$TEST_ARCH"
swiftc -target "$TEST_ARCH-apple-macosx13.0" "$PROJECT_DIR/Sources/ChargeHardware/BatteryReader.swift" "$PROJECT_DIR/Sources/ChargeHardware/TelemetryMath.swift" "$PROJECT_DIR/Sources/ChargeHardware/SMCFirmwareChargeController.swift" "$PROJECT_DIR/Sources/ChargeHardware/ChargeRecoveryStore.swift" "$PROJECT_DIR/Sources/ChargeHardware/SMCKeyIO.swift" "$PROJECT_DIR/Sources/ChargeHardware/SMCFirmwareProbe.swift" "$PROJECT_DIR/Tests/HardwareSmoke/SMCKeyIOTests.swift" -o "$PROJECT_DIR/.build/smc-tests/wire-$TEST_ARCH"
/usr/bin/arch "-$TEST_ARCH" "$PROJECT_DIR/.build/smc-tests/wire-$TEST_ARCH"
swiftc -target "$TEST_ARCH-apple-macosx13.0" "$PROJECT_DIR/Sources/ChargeHardware/BatteryReader.swift" "$PROJECT_DIR/Sources/ChargeHardware/TelemetryMath.swift" "$PROJECT_DIR/Sources/ChargeHardware/SMCChargeController.swift" "$PROJECT_DIR/Sources/ChargeHardware/SMCFirmwareChargeController.swift" "$PROJECT_DIR/Sources/ChargeHardware/ChargeRecoveryStore.swift" "$PROJECT_DIR/Sources/ChargeHardware/FirmwareInflowAssertion.swift" "$PROJECT_DIR/Sources/ChargeHardware/ChargeBackendSession.swift" "$PROJECT_DIR/Tests/HardwareSmoke/ChargeBackendSessionTests.swift" -o "$PROJECT_DIR/.build/smc-tests/backends-$TEST_ARCH"
/usr/bin/arch "-$TEST_ARCH" "$PROJECT_DIR/.build/smc-tests/backends-$TEST_ARCH"
swiftc -target "$TEST_ARCH-apple-macosx13.0" "$PROJECT_DIR/Sources/ChargeHardware/BatteryReader.swift" "$PROJECT_DIR/Sources/ChargeHardware/TelemetryMath.swift" "$PROJECT_DIR/Sources/ChargeHardware/FirmwareInflowAssertion.swift" "$PROJECT_DIR/Tests/HardwareSmoke/FirmwareInflowAssertionTests.swift" -o "$PROJECT_DIR/.build/smc-tests/inflow-$TEST_ARCH"
/usr/bin/arch "-$TEST_ARCH" "$PROJECT_DIR/.build/smc-tests/inflow-$TEST_ARCH"
swiftc -target "$TEST_ARCH-apple-macosx13.0" "$PROJECT_DIR/Sources/ChargeHardware/BatteryReader.swift" "$PROJECT_DIR/Sources/ChargeHardware/TelemetryMath.swift" "$PROJECT_DIR/Sources/ChargeHardware/SMCChargeController.swift" "$PROJECT_DIR/Sources/ChargeHardware/SMCFirmwareChargeController.swift" "$PROJECT_DIR/Sources/ChargeHardware/ChargeRecoveryStore.swift" "$PROJECT_DIR/Sources/ChargeHardware/FirmwareInflowAssertion.swift" "$PROJECT_DIR/Sources/ChargeHardware/ChargeBackendSession.swift" "$PROJECT_DIR/Sources/ChargeCore/FirmwareCommand.swift" "$PROJECT_DIR/Sources/ChargeCore/FirmwareControlSession.swift" "$PROJECT_DIR/Tests/HardwareSmoke/FirmwareDischargeSessionTests.swift" -o "$PROJECT_DIR/.build/smc-tests/discharge-$TEST_ARCH"
/usr/bin/arch "-$TEST_ARCH" "$PROJECT_DIR/.build/smc-tests/discharge-$TEST_ARCH"
